public class Solution {
  /**
   * 单遍状态机：inQuotes / started（本字段是否已经开始，用于区分"字段开头的引号"与"字段中间的引号"）。
   * 引用字段里 "" -> 一个字面量引号；未加引号的字段不 trim；空行 -> 零字段。
   * 只复用一个 StringBuilder，避免循环内字符串拼接的 O(n^2) 复制。
   */
  public static String[] parseCsvLine(String line, char delim) {
    if (line == null || line.isEmpty()) return new String[0];
    java.util.List<String> out = new java.util.ArrayList<>();
    StringBuilder field = new StringBuilder(line.length());
    boolean inQuotes = false;
    boolean started = false;
    for (int k = 0; k < line.length(); k++) {
      char c = line.charAt(k);
      if (inQuotes) {
        if (c == '"') {
          if (k + 1 < line.length() && line.charAt(k + 1) == '"') {
            field.append('"');                    // "" -> 字面量引号
            k++;                                  // 注意：for 循环还会再 ++，正好跳过转义的第二个引号
          } else {
            inQuotes = false;                     // 闭合引号
          }
        } else {
          field.append(c);                        // 引号内的 delim/空白/代理对都原样保留
        }
      } else if (c == '"' && !started) {
        inQuotes = true;
        started = true;
      } else if (c == '"') {
        throw new IllegalArgumentException("quote in the middle of an unquoted field");
      } else if (c == delim) {
        out.add(field.toString());
        field.setLength(0);
        started = false;
      } else {
        field.append(c);
        started = true;
      }
    }
    if (inQuotes) throw new IllegalArgumentException("unbalanced quote");
    out.add(field.toString());                    // 尾部字段（哪怕是空串）必须保留
    return out.toArray(new String[0]);
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：直接用 String.split。默认 limit=0 会丢掉全部尾部空字段，
  // 引号与 "" 转义完全不处理（引号被当成普通字符留在字段里）。
  public static String[] parseCsvLine(String line, char delim) {
    if (line == null || line.isEmpty()) return new String[0];
    return line.split(java.util.regex.Pattern.quote(String.valueOf(delim)));
  }
}
